// Step 2: Inbound Email Intent Classification Engine
const body = $input.first().json.body || $input.first().json;

const rawText = String(body.message_body || body.text || '').trim();
const senderEmail = (body.sender_email || body.from || '').trim().toLowerCase();
const businessId = body.business_id || body.lead_id || null;

if (!rawText) {
  throw new Error('Validation failed: "message_body" or "text" parameter is required.');
}

const lower = rawText.toLowerCase();
let intent = 'QUESTION';
let action = 'NEEDS_HUMAN_REVIEW';
let autoCancelFollowups = true;
let suggestedReply = '';

// 1. Unsubscribe Detection
if (/unsubscribe|remove me|opt[ -]?out|stop emailing|cease/i.test(lower)) {
  intent = 'UNSUBSCRIBE';
  action = 'SUPPRESS_AND_CANCEL';
  suggestedReply = 'Understood. You have been removed from all future communications.';
}
// 2. Explicit Negative / Not Interested
else if (/not interested|no thanks|pass|wrong person|not right now|stop/i.test(lower)) {
  intent = 'NOT_INTERESTED';
  action = 'CLOSE_LEAD_CANCEL_FOLLOWUPS';
  suggestedReply = 'Thank you for letting us know. Wishing your business all the best.';
}
// 3. Positive / Discovery Interest
else if (/send info|interested|tell me more|sounds good|demo|pricing|cost|call|meet|schedule|zoom/i.test(lower)) {
  intent = 'POSITIVE';
  // Strict Agency OS Rule: Demo generation is HELD until requirements are gathered
  action = 'NOTIFY_CEO_REQUIREMENTS_GATHERING';
  suggestedReply = 'Glad to connect! To ensure we prepare the exact right solution for your team, could you share your primary goals or let us know a convenient time for a brief 10-minute discovery call?';
}
// 4. Commercial Objection
else if (/too expensive|already have|competitor|no budget/i.test(lower)) {
  intent = 'OBJECTION';
  action = 'ROUTE_TO_SALES_REBUTTAL';
  suggestedReply = 'Understood completely. Just out of curiosity, are you currently handling this internally or with an existing partner?';
}

return [{
  json: {
    status: 'PROCESSED',
    business_id: businessId,
    sender_email: senderEmail,
    intent: intent,
    action_required: action,
    auto_cancel_followups: autoCancelFollowups,
    demo_generation_held: true,
    suggested_response: suggestedReply,
    classified_at: new Date().toISOString()
  }
}];
